                  {
                    "code": "G012",
                    "name": "Transaction failed"
                  },
                  {
                    "code": "G013",
                    "name": "Previous instalments not received"
                  },
                  {
                    "code": "G014",
                    "name": "Incorrectly marked as deceased"
                  },
                  {
                    "code": "G015",
                    "name": "Previous landowner incorrectly marked as deceased"
                  },
                  {
                    "code": "G016",
                    "name": "Incorrectly marked as ineligible"
                  },
                  {
                    "code": "G017",
                    "name": "Voluntary surrender made by mistake"
                  },
                  {
                    "code": "G018",
                    "name": "Incorrectly marked under suspected cases"
                  },
                  {
                    "code": "G019",
                    "name": "Problem updating land details"
                  },
                  {
                    "code": "G020",
                    "name": "Problem seeding Aadhaar in the bank account"
                  },
                  {
                    "code": "G021",
                    "name": "Problem with biometric eKYC"
                  },
                  {
                    "code": "G022",
                    "name": "Problem with facial eKYC"
                  },
                  {
                    "code": "G023",
                    "name": "Self-registration pending approval"
                  },
                  {
                    "code": "G024",
                    "name": "Revocation of ineligibility pending approval"
                  },
                  {
                    "code": "G025",
                    "name": "Revocation of surrender pending approval"
                  },
                  {
                    "code": "G026",
                    "name": "Update of missing information pending approval"
                  },
                  {
                    "code": "G027",
                    "name": "Pending action on a suspected spouse or minor case"
                  },
                  {
                    "code": "G028",
                    "name": "Pending action on suspected incorrect land or previous-owner details"
                  },
                  {
                    "code": "G029",
                    "name": "Corruption"
                  },
                  {
                    "code": "G030",
                    "name": "Urgent"
                  }
                ]
              },
              "actions": [
                {
                  "action": "init",
                  "description": "Ask PM-KISAN to send a four-digit OTP to the mobile registered against this enrolment number. Needs only the enrolment number. Call before status or support: both require challenge.response carrying this OTP.",
                  "operationRef": "https://raw.githubusercontent.com/OpenAgriNet/network-specs/bv-migration/api/external/pm-kisan/grievance/v0.2/openapi.yaml#/paths/~1ChatbotOTP/post",
